/**
 * NODE 2 — Normalize   (Step 1: Ingestion)
 *
 * INPUT  : $input.first().json.body  -> the raw POST body received by "Intake Webhook"
 *          { id?: string, source: 'email'|'web_form'|'support_portal', message: string }
 *          (n8n puts the HTTP body under .body, headers under .headers, etc.)
 * OUTPUT : one item  { id, source, raw_message, received_at, pipeline:{provider, model, prompt_version, queue_base, started_ms} }
 * NEXT   : "Prompt Library" reads this item as $json.
 *          Later nodes re-read it with $('Normalize').first().json because each HTTP Request node
 *          REPLACES the item with the API response, so the original record must be fetched back by node name.
 *
 * HOW DATA PASSES BETWEEN NODES: every Code node must `return [{ json: {...} }]`; that array becomes the
 * input ($input / $json) of the next node along the arrow.
 */
const CONFIG = {
  provider: 'anthropic',    // 'anthropic' 
  model: 'claude-haiku-5-5',          // anthropic: claude-haiku-5-5 (cheap, fast, forced tool-use = schema-guaranteed JSON)
  prompt_version: 'v1',
  queue_base: 'https://webhook.site/31ed0ad2-d3f3-4988-90b9-896456e1f27d', // mock downstream system (webhook.site); each queue is a sub-path
};

// 1) read the webhook payload (first and only item of this execution)
const body = $input.first().json.body || {};
const message = String(body.message ?? body.text ?? '').trim();
if (!message) throw new Error('Rejected: empty message');   // throwing stops the run -> webhook caller gets an error

// 2) whitelist the source; anything else becomes 'unknown' (never trust the caller)
const allowedSources = ['email', 'web_form', 'support_portal'];
const source = allowedSources.includes(String(body.source || '').toLowerCase()) ? String(body.source).toLowerCase() : 'unknown';
// 3) stable id for the record and the output file name
const id = body.id || ('REQ-' + Date.now().toString(36).toUpperCase());

// 4) emit the normalized record + pipeline metadata used by every later node
return [{ json: {
  id,
  source,
  raw_message: message,
  received_at: new Date().toISOString(),
  pipeline: { ...CONFIG, started_ms: Date.now() },
} }];

/**
 * NODE 3 — Prompt Library
 *
 * INPUT  : $json = the normalized record from "Normalize" ({ id, source, raw_message, received_at, pipeline })
 * OUTPUT : the same record + `prompts` (all 3 system prompts and JSON schemas) + `request`
 *          (the ready-to-send classification request body for the next HTTP node)
 * NEXT   : "Classify (LLM)" sends  JSON.stringify($json.request)  as the HTTP body.
 *          "Parse Classification" and "Route & Escalate" later fetch the prompts with
 *          $('Prompt Library').first().json.prompts  to build the enrichment / summary requests.
 *
 * Keeping every prompt in ONE node makes them reviewable in one place (deliverable 4.3).
 */
const prompts = {
  classify: { system: "You are the intake triage classifier for ArcVault, a B2B software company. You receive ONE inbound customer message (from email, a web form, or the support portal) and classify it so it can be routed to the right team.\n\nCATEGORIES \u2014 choose exactly one as `category`:\n- Bug Report: a specific feature behaves incorrectly for the customer (errors, wrong results, broken buttons). Usually one account or user; the product as a whole is up.\n- Incident/Outage: the service, or a major part of it, is unavailable or badly degraded RIGHT NOW, typically for multiple users or a whole organization.\n- Billing Issue: invoices, charges, refunds, contract rates, payment methods.\n- Feature Request: asking for functionality that does not exist, or an improvement to existing functionality.\n- Technical Question: how-to, configuration, integration, or capability questions where nothing is broken.\n\nDISAMBIGUATION RULES:\n- \"not loading\" / \"down\" / \"can't access\" AND multiple users or a whole org -> Incident/Outage, not Bug Report.\n- A single user getting an error (e.g. HTTP 403 on login) -> Bug Report, even if that user is fully blocked.\n- \"Can we do X?\" about an existing capability -> Technical Question. \"We'd like X\" about a missing capability -> Feature Request.\n- If a message has two intents, choose the one with the highest business impact as `category` and put the other in `secondary_category` (otherwise use \"None\").\n\nPRIORITY RUBRIC:\n- High: customer blocked from core work, revenue affected, many users affected, or security-related.\n- Medium: degraded experience or a billing discrepancy; a workaround likely exists.\n- Low: requests, questions, and cosmetic issues with no time pressure.\n\nCONFIDENCE: a number from 0 to 1 for how certain you are about `category`. Use a value BELOW 0.7 when the message is vague, lacks details, or fits two categories almost equally. Do not inflate confidence.\n\nEXAMPLES (illustrative only):\n- \"The PDF report shows last month's totals instead of this month's for my account.\" -> Bug Report, Medium, 0.9\n- \"Nobody in our company can open the app since 9am, we all get a blank page.\" -> Incident/Outage, High, 0.95\n- \"Do you support SAML with Azure AD?\" -> Technical Question, Low, 0.85\n- \"Please add dark mode.\" -> Feature Request, Low, 0.95\n- \"Why was I billed in USD instead of EUR?\" -> Billing Issue, Medium, 0.9\n- \"help\" -> Technical Question, Low, 0.3\n\nOutput ONLY JSON matching the schema. `reasoning` is one sentence.", schema: {"type": "object", "properties": {"category": {"type": "string", "enum": ["Bug Report", "Feature Request", "Billing Issue", "Technical Question", "Incident/Outage"]}, "secondary_category": {"type": "string", "enum": ["None", "Bug Report", "Feature Request", "Billing Issue", "Technical Question", "Incident/Outage"]}, "priority": {"type": "string", "enum": ["Low", "Medium", "High"]}, "confidence": {"type": "number", "description": "0 to 1"}, "reasoning": {"type": "string"}}, "required": ["category", "secondary_category", "priority", "confidence", "reasoning"]} },
  enrich:   { system: "You extract structured facts from ONE inbound customer message for ArcVault support. Do NOT classify and do NOT invent facts: extract only what is explicitly in the message.\n\nFIELDS:\n- core_issue: the problem or request in ONE neutral sentence, max 25 words.\n- identifiers: every concrete identifier mentioned \u2014 account IDs or usernames, URLs, invoice numbers, error codes (e.g. \"HTTP 403\"), money amounts, dates/times, product features, third-party integrations (e.g. \"Okta\"). Empty array if none.\n- disputed_amount_usd: if the message disputes a charge, the amount IN DISPUTE in USD. Example: charged 1240 but expected 980 -> 260. \"Charged twice, $2,100 extra\" -> 2100. Use 0 when there is no billing dispute.\n- affected_scope: \"single_user\", \"multiple_users\", or \"unknown\" \u2014 based only on what the message says.\n- urgency_signal: none / low / medium / high, judged from the message content (words like \"asap\", \"urgent\", \"multiple users\", \"stopped\", \"since this morning\", deadlines) \u2014 NOT from the type of request.\n- urgency_evidence: the exact words that justify urgency_signal, or an empty string.\n\nOutput ONLY JSON matching the schema.",   schema: {"type": "object", "properties": {"core_issue": {"type": "string"}, "identifiers": {"type": "array", "items": {"type": "object", "properties": {"type": {"type": "string", "enum": ["account_id", "url", "invoice_number", "error_code", "amount", "datetime", "product_feature", "integration", "other"]}, "value": {"type": "string"}}, "required": ["type", "value"]}}, "disputed_amount_usd": {"type": "number"}, "affected_scope": {"type": "string", "enum": ["single_user", "multiple_users", "unknown"]}, "urgency_signal": {"type": "string", "enum": ["none", "low", "medium", "high"]}, "urgency_evidence": {"type": "string"}}, "required": ["core_issue", "identifiers", "disputed_amount_usd", "affected_scope", "urgency_signal", "urgency_evidence"]} },
  summary:  { system: "You write a 2\u20133 sentence handoff note for the ArcVault team that will receive this request. The audience is the team named in QUEUE. Say: what the customer reports, the key identifiers to look at, and the first thing the team should do. If ESCALATED is true, start the note with \"ESCALATED:\" and state the reason in plain words. Do not repeat the category/priority labels, do not add anything that is not in the input, no bullet points, plain English.\n\nOutput ONLY JSON matching the schema.",  schema: {"type": "object", "properties": {"summary": {"type": "string"}}, "required": ["summary"]} },
};
/**
 * buildRequest(prompt, userText) -> provider-specific request body
 *   prompt   : { system: string, schema: JSON Schema }   (one entry of `prompts`)
 *   userText : the customer message (plus context) placed in the user turn
 * Reads provider/model from the Normalize config so switching provider is a one-line change there.
 */
const buildRequest = (prompt, userText) => {
  const cfg = $('Normalize').first().json.pipeline;
  if (cfg.provider === 'anthropic') {
    // Forced tool use: the model must call `emit` with arguments matching input_schema -> schema-guaranteed JSON, no prose.
    return {
      model: cfg.model, max_tokens: 1024,   // no `temperature`: rejected (deprecated) by current Claude models
      system: prompt.system,
      messages: [{ role: 'user', content: userText }],
      tools: [{ name: 'emit', description: 'Return the structured result.', input_schema: prompt.schema }],
      tool_choice: { type: 'tool', name: 'emit' },
    };
  }
  return { 
    systemInstruction: { parts: [{ text: prompt.system }] },
    contents: [{ role: 'user', parts: [{ text: userText }] }],
    generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: prompt.schema },
  };
};
// the record coming from Normalize
const m = $input.first().json;
// build the Step-2 (classification) request; the HTTP node only serializes it
const request = buildRequest(prompts.classify, 'SOURCE: ' + m.source + '\nMESSAGE:\n' + m.raw_message);
return [{ json: { ...m, prompts, request } }];

/**
 * parseLLM(resp) -> the structured object the model produced
 *   Anthropic: resp.content[] contains a block { type:'tool_use', input:{...} } because we FORCE the `emit` tool,
 *              so `input` is already JSON that matches our schema.
 *   Gemini   : resp.candidates[0].content.parts[].text is a JSON string (JSON mode) -> strip fences, JSON.parse.
 * Throws if neither shape is present -> the run fails loudly instead of routing garbage.
 */
function parseLLM(resp) {
  if (Array.isArray(resp?.content)) {                       // anthropic
    const block = resp.content.find(b => b.type === 'tool_use');
    if (block && block.input) return block.input;
    throw new Error('LLM returned no tool_use block: ' + JSON.stringify(resp).slice(0, 200));
  }
  const text = (resp?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join(''); 
  const clean = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(clean); }
  catch (e) { throw new Error('LLM returned non-JSON output: ' + text.slice(0, 200)); }
}
/** usage(resp) -> token usage object of either provider (kept on the record for cost tracking) */
function usage(resp) { return resp?.usage || resp?.usageMetadata || null; }

/**
 * NODE 5 — Parse Classification   (Step 2: Classification)
 *
 * INPUT  : $input.first().json = the RAW Anthropic/Gemini API response from "Classify (LLM)"
 *          (the HTTP node replaced our record with the API answer — that is why we fetch the record back below)
 * READS  : $('Normalize').first().json        -> the original record
 *          $('Prompt Library').first().json   -> prompts, to build the next (enrichment) request
 * OUTPUT : record + classification{category, secondary_category, priority, confidence, reasoning}
 *          + llm_usage.classify + request (enrichment request body)
 * NEXT   : "Enrich (LLM)" sends JSON.stringify($json.request)
 *
 * WHY VALIDATE: the schema is forced, but downstream rules must never see an unexpected value.
 * Every field is checked against its allowed list and confidence is clamped to [0, 1].
 */
const base = $('Normalize').first().json;   // original record (id, source, raw_message, pipeline)
const resp = $input.first().json;             // raw API response
const c = parseLLM(resp);                     // -> { category, secondary_category, priority, confidence, reasoning }
const CATEGORIES = ['Bug Report', 'Feature Request', 'Billing Issue', 'Technical Question', 'Incident/Outage'];
const PRIORITIES = ['Low', 'Medium', 'High'];

const classification = {
  category: CATEGORIES.includes(c.category) ? c.category : 'Unknown',
  secondary_category: CATEGORIES.includes(c.secondary_category) ? c.secondary_category : 'None',
  priority: PRIORITIES.includes(c.priority) ? c.priority : 'Medium',
  confidence: Math.max(0, Math.min(1, Number(c.confidence) || 0)),
  reasoning: String(c.reasoning || ''),
};
const buildRequest = (prompt, userText) => {
  const cfg = $('Normalize').first().json.pipeline;
  if (cfg.provider === 'anthropic') {
    // Forced tool use: the model must call `emit` with arguments matching input_schema -> schema-guaranteed JSON, no prose.
    return {
      model: cfg.model, max_tokens: 1024,   // no `temperature`: rejected (deprecated) by current Claude models
      system: prompt.system,
      messages: [{ role: 'user', content: userText }],
      tools: [{ name: 'emit', description: 'Return the structured result.', input_schema: prompt.schema }],
      tool_choice: { type: 'tool', name: 'emit' },
    };
  }
  return { 
    systemInstruction: { parts: [{ text: prompt.system }] },
    contents: [{ role: 'user', parts: [{ text: userText }] }],
    generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: prompt.schema },
  };
};
const prompts = $('Prompt Library').first().json.prompts;
// prepare Step 3 (enrichment) — same message, different prompt/schema
const request = buildRequest(prompts.enrich, 'SOURCE: ' + base.source + '\nMESSAGE:\n' + base.raw_message);
return [{ json: { ...base, classification, llm_usage: { classify: usage(resp) }, request } }];

// Works for both providers: Anthropic tool_use block
function parseLLM(resp) {
  if (Array.isArray(resp?.content)) {                       // anthropic
    const block = resp.content.find(b => b.type === 'tool_use');
    if (block && block.input) return block.input;
    throw new Error('LLM returned no tool_use block: ' + JSON.stringify(resp).slice(0, 200));
  }
  const text = (resp?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');   // gemini
  const clean = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(clean); }
  catch (e) { throw new Error('LLM returned non-JSON output: ' + text.slice(0, 200)); }
}
/** usage(resp) -> token usage object of either provider (kept on the record for cost tracking) */
function usage(resp) { return resp?.usage || resp?.usageMetadata || null; }

/**
 * NODE 7 — Parse Enrichment   (Step 3: Enrichment)
 *
 * INPUT  : $input.first().json = RAW API response from "Enrich (LLM)"
 * READS  : $('Parse Classification').first().json -> record + classification (+ the old `request`, dropped here)
 * OUTPUT : record + enrichment{core_issue, identifiers[], disputed_amount_usd, affected_scope, urgency_signal, urgency_evidence}
 *          + llm_usage.enrich
 * NEXT   : "Route & Escalate" applies the deterministic rules on classification + enrichment.
 *
 * Types are normalized here (number >= 0, values from allowed lists) so the routing rules can trust them.
 */
const prev = $('Parse Classification').first().json;   // record so far
const resp = $input.first().json;
const e = parseLLM(resp);

const enrichment = {
  core_issue: String(e.core_issue || ''),
  identifiers: Array.isArray(e.identifiers) ? e.identifiers.filter(i => i && i.value).map(i => ({ type: String(i.type || 'other'), value: String(i.value) })) : [],
  disputed_amount_usd: Math.max(0, Number(e.disputed_amount_usd) || 0),
  affected_scope: ['single_user', 'multiple_users', 'unknown'].includes(e.affected_scope) ? e.affected_scope : 'unknown',
  urgency_signal: ['none', 'low', 'medium', 'high'].includes(e.urgency_signal) ? e.urgency_signal : 'none',
  urgency_evidence: String(e.urgency_evidence || ''),
};
const { request, ...rest } = prev;   // drop the consumed enrichment request from the record
return [{ json: { ...rest, enrichment, llm_usage: { ...prev.llm_usage, enrich: usage(resp) } } }];

/**
 * NODE 8 — Route & Escalate   (Step 4: Routing decision  +  Step 6: Human escalation flag)
 *
 * INPUT  : $input.first().json = record with classification + enrichment (from "Parse Enrichment")
 * READS  : $('Prompt Library').first().json.prompts -> to build the summary request
 * OUTPUT : record + routing{standard_queue, final_queue, final_queue_name, rule, fallback_used}
 *          + escalation{flagged, reasons[], human_review_required} + request (summary request body)
 * NEXT   : "Summarize (LLM)" sends JSON.stringify($json.request); the summary needs to know the
 *          destination queue and the escalation reasons, which is why routing runs BEFORE summarizing.
 *
 * DELIBERATELY NO LLM HERE: plain rules are auditable (every record carries its `reasons`),
 * unit-testable, cost zero tokens, and a support manager can change a threshold without touching prompts.
 */

const ROUTING_TABLE = {               // category -> standard destination queue
  'Bug Report':         { queue: 'engineering', name: 'Engineering' },
  'Incident/Outage':    { queue: 'engineering', name: 'Engineering' },   // also always escalated, see below
  'Billing Issue':      { queue: 'billing',     name: 'Billing' },
  'Feature Request':    { queue: 'product',     name: 'Product' },
  'Technical Question': { queue: 'it-security', name: 'IT/Security' },
};
const ESCALATION_QUEUE = { queue: 'escalation', name: 'Escalation (Human Review)' };

const CONFIDENCE_THRESHOLD = 0.70;    // required by the assessment
const BILLING_ESCALATION_USD = 500;   // "billing error > $500" — interpreted as the amount IN DISPUTE, not the invoice total (documented assumption)
const ESCALATION_KEYWORDS = ['outage', 'down for all', 'all users', 'multiple users', 'everyone', 'data loss', 'breach', 'security incident', 'hacked'];

const r = $input.first().json;
const { classification: c, enrichment: e } = r;
const text = r.raw_message.toLowerCase();

// collect every escalation reason that applies (any one is enough to escalate)
const reasons = [];
if (c.confidence < CONFIDENCE_THRESHOLD) reasons.push(`low_confidence:${c.confidence.toFixed(2)}<${CONFIDENCE_THRESHOLD}`);
if (c.category === 'Incident/Outage') reasons.push('category:incident_outage');
if (c.category === 'Unknown') reasons.push('category:unknown');
for (const k of ESCALATION_KEYWORDS) if (text.includes(k)) reasons.push(`keyword:${k}`);
if (e.disputed_amount_usd > BILLING_ESCALATION_USD) reasons.push(`billing_dispute_usd:${e.disputed_amount_usd}>${BILLING_ESCALATION_USD}`);
if (e.affected_scope === 'multiple_users' && ['Bug Report', 'Incident/Outage'].includes(c.category)) reasons.push('scope:multiple_users');

// standard destination from the table; fallback if the category is unknown or confidence is low
const standard = ROUTING_TABLE[c.category];
const fallback_used = !standard || c.confidence < CONFIDENCE_THRESHOLD;
const flagged = reasons.length > 0;
const final = flagged ? ESCALATION_QUEUE : standard;   // escalated records go to the separate human-review queue

const routing = {
  standard_queue: standard ? standard.queue : ESCALATION_QUEUE.queue,
  final_queue: final.queue,
  final_queue_name: final.name,
  rule: standard ? `category=${c.category} -> ${standard.queue}` : 'no table match -> escalation',
  fallback_used,
};
const escalation = { flagged, reasons, human_review_required: flagged };

const buildRequest = (prompt, userText) => {
  const cfg = $('Normalize').first().json.pipeline;
  if (cfg.provider === 'anthropic') {
    // Forced tool use: the model must call `emit` with arguments matching input_schema -> schema-guaranteed JSON, no prose.
    return {
      model: cfg.model, max_tokens: 1024,   // no `temperature`: rejected (deprecated) by current Claude models
      system: prompt.system,
      messages: [{ role: 'user', content: userText }],
      tools: [{ name: 'emit', description: 'Return the structured result.', input_schema: prompt.schema }],
      tool_choice: { type: 'tool', name: 'emit' },
    };
  }
  return { // gemini
    systemInstruction: { parts: [{ text: prompt.system }] },
    contents: [{ role: 'user', parts: [{ text: userText }] }],
    generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: prompt.schema },
  };
};
const prompts = $('Prompt Library').first().json.prompts;
// context handed to the summary prompt (Step 5) — the receiving team's point of view
const summaryInput = [
  'QUEUE: ' + routing.final_queue_name,
  'ESCALATED: ' + escalation.flagged + (escalation.flagged ? ' (' + escalation.reasons.join(', ') + ')' : ''),
  'CATEGORY: ' + c.category + ' | PRIORITY: ' + c.priority,
  'CORE ISSUE: ' + e.core_issue,
  'IDENTIFIERS: ' + JSON.stringify(e.identifiers),
  'RAW MESSAGE:\n' + r.raw_message,
].join('\n');
const request = buildRequest(prompts.summary, summaryInput);
return [{ json: { ...r, routing, escalation, request } }];

/**
 * parseLLM(resp) -> the structured object the model produced
 *   Anthropic: resp.content[] contains a block { type:'tool_use', input:{...} } because we FORCE the `emit` tool,
 *              so `input` is already JSON that matches our schema.
 *   Gemini   : resp.candidates[0].content.parts[].text is a JSON string (JSON mode) -> strip fences, JSON.parse.
 * Throws if neither shape is present -> the run fails loudly instead of routing garbage.
 */
function parseLLM(resp) {
  if (Array.isArray(resp?.content)) {                       // anthropic
    const block = resp.content.find(b => b.type === 'tool_use');
    if (block && block.input) return block.input;
    throw new Error('LLM returned no tool_use block: ' + JSON.stringify(resp).slice(0, 200));
  }
  const text = (resp?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');   // gemini
  const clean = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(clean); }
  catch (e) { throw new Error('LLM returned non-JSON output: ' + text.slice(0, 200)); }
}
/** usage(resp) -> token usage object of either provider (kept on the record for cost tracking) */
function usage(resp) { return resp?.usage || resp?.usageMetadata || null; }

/**
 * NODE 10 — Build Record   (Step 5: Structured output)
 *
 * INPUT  : $input.first().json = RAW API response from "Summarize (LLM)"  -> { summary }
 * READS  : $('Route & Escalate').first().json -> everything computed so far
 * OUTPUT : the FINAL record (this exact object is what lands in output/records.json):
 *          { id, received_at, processed_at, source, raw_message, classification, enrichment,
 *            routing, escalation, summary, pipeline{model, prompt_version, queue_base, processing_ms, llm_usage} }
 * NEXT   : three consumers in parallel —
 *          "Respond to Webhook"  returns it to the caller,
 *          "Record to JSON File" -> "Write Record to Disk" persist it as /data/records/<id>.json,
 *          "Dispatch to Queue"   POSTs it to <queue_base>/<routing.final_queue>.
 */
const prev = $('Route & Escalate').first().json;   // record with routing + escalation
const resp = $input.first().json;
const s = parseLLM(resp);                           // -> { summary }

const record = {
  id: prev.id,
  received_at: prev.received_at,
  processed_at: new Date().toISOString(),
  source: prev.source,
  raw_message: prev.raw_message,
  classification: prev.classification,
  enrichment: prev.enrichment,
  routing: prev.routing,
  escalation: prev.escalation,
  summary: String(s.summary || ''),
  pipeline: {
    model: prev.pipeline.model,
    prompt_version: prev.pipeline.prompt_version,
    queue_base: prev.pipeline.queue_base,
    processing_ms: Date.now() - prev.pipeline.started_ms,
    llm_usage: { ...prev.llm_usage, summary: usage(resp) },
  },
};
return [{ json: record }];
